class DelayTest {
    @Test
    fun delayIsSkipped() = runTest {
        val start = currentTime
        delay(10_000)                                   // returns immediately in real time
        assertEquals(10_000, currentTime - start)       // but 10 s of virtual time passed
    }
}

@Test
fun standardDispatcherQueues() = runTest {
    var value = 0
    launch { value = 1 }             // queued, hasn't run yet
    assertEquals(0, value)

    runCurrent()                     // run everything that is due now
    assertEquals(1, value)
}

@Test
fun unconfinedStartsEagerly() = runTest(UnconfinedTestDispatcher()) {
    var value = 0
    launch { value = 1 }             // already ran
    assertEquals(1, value)
}

@Test
fun tasksRunAtTheirVirtualTime() = runTest {
    val log = mutableListOf<String>()
    launch { delay(1_000); log += "first" }
    launch { delay(2_000); log += "second" }

    advanceTimeBy(999)
    assertTrue(log.isEmpty())               // nothing is due yet

    advanceTimeBy(1)                        // clock is now exactly 1000
    runCurrent()                            // tasks due at exactly 1000 only run now
    assertEquals(listOf("first"), log)

    advanceUntilIdle()                      // run everything that is left
    assertEquals(listOf("first", "second"), log)
}

class Repository(private val io: CoroutineDispatcher = Dispatchers.IO) {
    suspend fun load(): String = withContext(io) { delay(500); "data" }
}

@Test
fun loadsWithVirtualTime() = runTest {
    val dispatcher = StandardTestDispatcher(testScheduler)   // same scheduler as runTest
    val repo = Repository(io = dispatcher)

    val result = repo.load()          // the 500 ms delay is virtual
    assertEquals("data", result)
    assertEquals(500, currentTime)
}

@Test
fun stateReflectsLoad() = runTest {
    val viewModel = ProfileViewModel(FakeUserRepository())
    val states = mutableListOf<UiState>()

    backgroundScope.launch(UnconfinedTestDispatcher(testScheduler)) {
        viewModel.state.toList(states)     // never completes, cancelled at the end of the test
    }

    viewModel.load()
    runCurrent()

    assertEquals(UiState.Content("Ana"), states.last())
}

@Test
fun emitsLoadingThenContent() = runTest {
    viewModel.state.test {
        assertEquals(UiState.Loading, awaitItem())     // initial value

        viewModel.load()
        assertEquals(UiState.Content("Ana"), awaitItem())

        expectNoEvents()
        cancelAndIgnoreRemainingEvents()
    }
}

@Test
fun failingFlowEndsWithError() = runTest {
    failingFlow().test {
        assertIs<IOException>(awaitError())
    }
}

@Test
fun eventIsReceivedWhenCollectedFirst() = runTest {
    val events = MutableSharedFlow<UiEvent>()

    events.test {                              // collector is running now
        events.emit(UiEvent.Saved)
        assertEquals(UiEvent.Saved, awaitItem())
    }
}

@Test
fun channelBuffersEventsSentEarly() = runTest {
    val channel = Channel<UiEvent>(Channel.BUFFERED)
    channel.send(UiEvent.Saved)                // sent before anyone collects

    channel.receiveAsFlow().test {
        assertEquals(UiEvent.Saved, awaitItem())
        cancelAndIgnoreRemainingEvents()
    }
}

class FakeUserRepository : UserRepository {
    private val users = MutableStateFlow<List<User>>(emptyList())

    override fun observeUsers(): Flow<List<User>> = users

    fun setUsers(list: List<User>) { users.value = list }   // the test drives the fake
}

